{
  "contract": "SimpleSalesEth",
  "closure": {
    "site_function": "buy",
    "site_call": ".safeTransferFrom",
    "functions": ["buy", "withdrawAllFailedCredits"],
    "justification": "withdrawAllFailedCredits affects the exposed state by writing to failedTransferCredits and _ethBal."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": ["buy", "withdrawAllFailedCredits"],
    "nesting_bound": {
      "buy": 1
    }
  },
  "phases": {
    "function": "buy",
    "pre": {
      "name": "pre",
      "from_marker": "pre_phase_start",
      "to_marker": "call_site_entry"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "call_site_entry",
      "to_marker": "call_site_exit"
    },
    "post": {
      "name": "post",
      "from_marker": "call_site_exit",
      "to_marker": "post_phase_end"
    },
    "linearization_point": "call_site_exit"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "tracks the amount of ETH in transit during the callback window",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "_sum_failedTransferCredits == snapPre + inFlight",
    "stable_formula": "_sum_failedTransferCredits == snapPre",
    "kind": "conserve"
  },
  "composition": {
    "target_property": "_sum_failedTransferCredits <= _ethBal",
    "rule": "conservation during external call ensuring _sum_failedTransferCredits is tracked by inFlight, maintaining backing relation."
  }
}
